solutionReferences.cpp:
#include <iostream>

int main() {
    int nota = 85;
    if (nota >= 90) {
        std::cout << "Excelente (A)" << "\n";
    } else if (nota >= 80) {
        std::cout << "Muy Bien (B)" << "\n";
    } else if (nota >= 70) {
        std::cout << "Bien (C)" << "\n";
    } else {
        std::cout << "Necesitas mejorar (D)" << "\n";
    }
    return 0;
}
